from pathlib import Path
import json,re,html
R=Path(__file__).resolve().parents[1]
# Read the already-authored shell without re-running the one-time upgrade.
home=(R/'index.html').read_text(encoding='utf-8')
header=re.search(r'<header class="ca-header">[\s\S]*?</header>',home).group()
footer=re.search(r'<footer class="ca-footer">[\s\S]*?</footer>',home).group()
def write(p,s):
    p=R/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf-8')
def page(title,desc,body,script='commerce.js'):
    return f'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}｜クルーアセント</title><meta name="description" content="{desc}"><meta name="robots" content="noindex,follow"><meta name="theme-color" content="#10243a"><link rel="icon" href="assets/brand/icon-32.png"><link rel="stylesheet" href="assets/css/base.css"><link rel="stylesheet" href="assets/css/upgrade.css"><link rel="stylesheet" href="assets/css/commerce.css"><script defer src="assets/js/upgrade.js"></script><script defer src="assets/js/{script}"></script></head><body class="ca-page"><a class="skip-link" href="#main">本文へスキップ</a>{header}<main id="main">{body}</main>{footer}</body></html>'''
def intro(label,title,desc):
    return f'<section class="ca-intro wrap"><p class="ca-kicker">{label}</p><h1>{title}</h1><p class="ca-intro-lead">{desc}</p></section>'
plans=json.loads((R/'data/commerce-plans.json').read_text(encoding='utf-8'))
plan_options='<option value="undecided">まだ決めていない</option>'+''.join(f'<option value="{p["id"]}">{p["name"]} / {p["price"]:,}円</option>' for p in plans)
consent='''<label class="ca-check"><input type="checkbox" name="consent" required><span><a href="privacy.html" target="_blank" rel="noopener">個人情報の取り扱い</a>を確認し、相談対応・予約管理のための利用に同意します。</span></label><div class="ca-honeypot" aria-hidden="true"><label>この欄は空欄にしてください<input name="website_confirm" tabindex="-1" autocomplete="off"></label></div>'''
contact=intro('FREE HEARING SHEET','お話の前に、<br>少しだけ、教えてください。','今の状況と、これから実現したいこと。分かる範囲のご記入で大丈夫です。このシートの送信で、制作契約や料金は発生しません。')+'''<div class="wrap ca-content ca-form-layout"><aside class="ca-form-aside"><p class="ca-kicker">YOUR FIRST STEP</p><h2>まとまっていない<br>思いも、そのままで。</h2><p>所要時間の目安は5〜8分。<br>必須項目には「必須」と表示しています。</p><ol><li>事業・ご希望を入力</li><li>内容を確認して送信</li><li>内容を確認後、ご連絡</li></ol><div class="ca-aside-note"><strong>話しながら整理したい方へ</strong><p>60分の無料ヒアリングを予約できます。シートの送信だけでも相談可能です。</p><a href="booking.html">空いている日時を見る →</a></div></aside><div><div class="ca-notice" data-preview-note hidden></div><form id="hearing-form" class="ca-form" novalidate><div id="hearing-fields"><section class="ca-form-section"><p class="ca-kicker">01 / ABOUT YOUR BUSINESS</p><h2>あなたと、事業のこと。</h2><div class="ca-field-grid"><label>お名前 <span class="ca-required">必須</span><input name="name" autocomplete="name" required maxlength="100"></label><label>メールアドレス <span class="ca-required">必須</span><input type="email" name="email" autocomplete="email" required maxlength="254"></label></div><label>事業名・屋号 <span class="ca-optional">任意</span><input name="business" autocomplete="organization" maxlength="150"></label><div class="ca-field-grid"><label>ご利用の目的 <span class="ca-required">必須</span><select name="customerType" required><option value="business">法人・個人事業主として利用</option><option value="consumer">事業目的ではない個人利用</option></select></label><label>業種 <span class="ca-optional">任意</span><input name="industry" maxlength="120" placeholder="例：美容室、建設、士業"></label></div><label>事業内容 <span class="ca-optional">任意</span><textarea name="description" maxlength="2000" rows="3" placeholder="どなたに、どのようなサービスを提供していますか？"></textarea></label><label>現在のサイト・SNS <span class="ca-optional">任意</span><input type="url" name="currentUrl" maxlength="1000" placeholder="https://" inputmode="url"></label></section><section class="ca-form-section"><p class="ca-kicker">02 / YOUR NEXT CHAPTER</p><h2>つくりたいサイトのこと。</h2><label>相談したいこと <span class="ca-required">必須</span><textarea name="goals" required minlength="10" maxlength="4000" rows="5" placeholder="例：紹介で来てくださる方が、サービスや料金を確認できるサイトにしたい。文章や写真の準備から相談したい。"></textarea><small>10文字以上。まだ決まっていないことも、そのままご記入ください。</small></label><div class="ca-field-grid"><label>気になっているプラン <span class="ca-optional">任意</span><select name="plan">'''+plan_options+'''</select></label><label>希望する時期 <span class="ca-optional">任意</span><select name="timing"><option>相談して決めたい</option><option>1か月以内</option><option>1〜3か月以内</option><option>3か月以降</option></select></label></div><label>素材の準備状況 <span class="ca-optional">任意</span><select name="materials"><option>まだ準備していない</option><option>原稿・写真の一部がある</option><option>原稿・写真・ロゴがそろっている</option><option>整理から相談したい</option></select></label><label>参考サイト・必要な機能など <span class="ca-optional">任意</span><textarea name="notes" maxlength="3000" rows="3" placeholder="好みの雰囲気、参考URL、予約や決済など。パスワード・カード情報は記入しないでください。"></textarea></label><label>Web診断36の結果 <span class="ca-optional">任意</span><input name="diagnosis" maxlength="120" placeholder="例：CA09 洗練集客型サイト"></label></section><section class="ca-form-section"><p class="ca-kicker">03 / HOW WE CONNECT</p><h2>ご連絡について。</h2><label>希望する相談方法<select name="communication"><option value="email">メールで相談したい</option><option value="online">オンラインで話したい（日時は別途予約）</option><option value="undecided">相談して決めたい</option></select></label>'''+consent+'''<p class="ca-fine">営業メールの購読登録は行いません。ご入力内容はお問い合わせ対応のために使用します。</p><button class="ca-button" type="submit">入力内容を確認する <span>→</span></button></section></div><section id="hearing-review" hidden tabindex="-1"><p class="ca-kicker">REVIEW YOUR MESSAGE</p><h2>この内容で送信しますか？</h2><dl class="ca-review-list" id="hearing-summary"></dl><div class="ca-actions"><button class="ca-button ca-button-line" type="button" id="hearing-back">入力を修正する</button><button class="ca-button" type="button" id="hearing-send">無料ヒアリングシートを送信 <span>↗</span></button></div></section><p id="hearing-status" class="ca-status" role="status" aria-live="polite"></p></form><section id="hearing-success" class="ca-success" hidden tabindex="-1"><span class="ca-success-mark">✓</span><p class="ca-kicker">THANK YOU</p><h2>ご相談を受け付けました。</h2><p>受付番号：<strong id="hearing-reference"></strong></p><p>受付内容を保存しました。メール通知が有効な場合は確認メールをお送りします。返信までの案内は運営者からの連絡をご確認ください。</p><div class="ca-notice" id="hearing-mail-note"></div><div class="ca-actions"><a class="ca-button" href="booking.html">相談日時も予約する <span>↗</span></a><a class="ca-text-link" href="index.html">ホームへ戻る →</a></div></section><noscript><p class="ca-notice">シートの確認・送信にはJavaScriptが必要です。ブラウザの設定を有効にしてご利用ください。</p></noscript></div></div>'''
write('contact.html',page('無料ヒアリングシート','制作前の無料相談。事業内容・希望・素材の準備状況を、分かる範囲でお知らせください。',contact))
